var total = "много";

console.log(total + 1);

const counter = (function () {
  let count = 0;

  function inc() {
    count += 1;
    return count;
  }

  return { inc, value: () => count };
})();

console.log(counter.inc(), counter.inc());
console.log(counter.value(), counter.count);

function createCounter(start) {
  let count = start;
  return {
    inc() {
      count += 1;
    },
    value() {
      return count;
    },
  };
}

const a = createCounter(10);
const b = createCounter(0);
a.inc();
a.inc();
b.inc();
console.log(a.value(), b.value());
